const palettes=[
 {id:'sunshine',name:'Sunshine Club',frame:'Yellow',hex:'#fce300',letter:'Pine Green',cap:'Pine Green',ink:'#034638',stage:'#e7eddd',letterHex:'#034638',capHex:'#034638'},
 {id:'tangerine',name:'Tangerine Rally',frame:'Orange',hex:'#ff671f',letter:'Reflex Blue',cap:'Reflex Blue',ink:'#001489',stage:'#cde8f2',letterHex:'#001489',capHex:'#001489'},
 {id:'poolside',name:'Poolside Play',frame:'Navy Blue',hex:'#0086d6',letter:'White',cap:'Yellow',ink:'#06384b',stage:'#e3f3f5',letterHex:'#ffffff',capHex:'#fce300'}
];
let selected=0;
try{const saved=localStorage.getItem('pongfetch-palette');const i=palettes.findIndex(p=>p.id===saved);if(i>=0)selected=i;}catch{}
function choosePalette(index){
 selected=index;const p=palettes[index];const style=document.documentElement.style;
 for(const [key,value] of Object.entries({'--ink':p.ink,'--accent':p.hex,'--stage':p.stage,'--on-accent':index===2?'#ffffff':p.ink,'--frame':p.hex,'--letter':p.letterHex,'--cap':p.capHex}))style.setProperty(key,value);
 document.querySelectorAll('.swatches').forEach(group=>{group.innerHTML=palettes.map((v,i)=>`<button type="button" class="swatch" data-palette="${i}" style="--swatch:${v.hex};--tick:${i===2?'white':v.ink}" aria-pressed="${i===index}" aria-label="${v.name}: ${v.frame} frame, ${v.letter} lettering, ${v.cap} cap" title="${v.name}"></button>`).join('');});
 document.querySelectorAll('.palette-title').forEach(el=>el.textContent=p.name);
 document.querySelectorAll('.product-hero').forEach(el=>{el.src=`assets/${p.id}-hero.webp`;el.alt=`${p.frame} PongFetch frame, ${p.cap} clamp cap, dark green net, white balls and white PVC handle`;});
 document.querySelectorAll('.product-front').forEach(el=>el.src=`assets/${p.id}-front.webp`);
 document.querySelectorAll('.material-specs').forEach(el=>el.innerHTML=`<span><i class="dot" style="--colour:${p.hex}"></i>Frame / ${p.frame}</span><span><i class="dot" style="--colour:${p.letterHex}"></i>Type / ${p.letter}</span><span><i class="dot" style="--colour:${p.capHex}"></i>Cap / ${p.cap}</span>`);
 document.querySelector('.stage-caption span:last-child').textContent=`0${index+1} / 03`;
 try{localStorage.setItem('pongfetch-palette',p.id);}catch{}
 if(typeof updateKit==='function')updateKit();
}
document.addEventListener('click',event=>{const btn=event.target.closest('[data-palette]');if(btn){const group=btn.parentElement;choosePalette(Number(btn.dataset.palette));group?.querySelector(`[data-palette="${selected}"]`)?.focus();}});
function route(){const id=location.hash.slice(1)||'home';const valid=['home','guide','downloads','kit','license'].includes(id)?id:'home';document.querySelectorAll('.page').forEach(el=>el.hidden=el.id!==valid);document.querySelectorAll('.header nav a').forEach(el=>{if(el.hash===`#${valid}`)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});document.title=`PongFetch — ${({home:'Pick. Play.',guide:'Build guide',downloads:'Get the files',kit:'Explore the kit',license:'License & reuse'})[valid]}`;window.scrollTo(0,0);}
window.addEventListener('hashchange',()=>{route();document.querySelector('main').focus({preventScroll:true});});
function updateKit(){const p=palettes[selected];const quantity=Number(document.querySelector('#kit-quantity').value);document.querySelector('#kit-summary').innerHTML=`<img class="summary-image" src="assets/${p.id}-front.webp" alt="${p.name} front view"><h3>${p.name}</h3><dl><div><dt>Quantity</dt><dd>${quantity} ${quantity===1?'kit':'kits'}</dd></div><div><dt>Frame</dt><dd>${p.frame}</dd></div><div><dt>Lettering</dt><dd>${p.letter}</dd></div><div><dt>Clamp cap</dt><dd>${p.cap}</dd></div><div><dt>Price &amp; availability</dt><dd>To be confirmed</dd></div></dl>`;}
const dialog=document.querySelector('#kit-dialog');
document.querySelector('#review-kit').addEventListener('click',()=>{updateKit();document.querySelector('#save-status').textContent='';dialog.showModal();});
document.querySelector('#close-kit').addEventListener('click',()=>dialog.close());
document.querySelector('#kit-quantity').addEventListener('change',updateKit);
document.querySelector('#save-kit').addEventListener('click',()=>{const p=palettes[selected];const qty=document.querySelector('#kit-quantity').value;const text=`PongFetch — Kit selection (local preview)\n\nPalette: ${p.name}\nQuantity: ${qty}\nFrame: Bambu PETG Basic ${p.frame} (${p.hex})\nLettering: ${p.letter}\nClamp cap: ${p.cap}\n\nContents: printed frame, cap, collet and digital build guide.\nNet, PVC pipe and balls not included.\nPricing, availability and final contents to be confirmed.\nRev 3.0 frame lettering is included in the two-colour 3MF. Set filament colours in your slicer.\n\nThis is a saved selection, not an order. No payment or information has been sent.\n`;const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='PongFetch-kit-selection.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('#save-status').textContent='Your selection file is ready.';});
let completed=[];try{const v=JSON.parse(localStorage.getItem('pongfetch-build-progress')||'[]');if(Array.isArray(v))completed=v.filter(n=>Number.isInteger(n)&&n>=0&&n<5);}catch{}
function updateProgress(){const count=document.querySelectorAll('[data-step]:checked').length;document.querySelector('#build-progress').value=count;document.querySelector('#progress-label').textContent=`${count} of 5 steps complete`;const values=[...document.querySelectorAll('[data-step]:checked')].map(el=>Number(el.dataset.step));try{localStorage.setItem('pongfetch-build-progress',JSON.stringify(values));}catch{}}
document.querySelectorAll('[data-step]').forEach(el=>{el.checked=completed.includes(Number(el.dataset.step));el.addEventListener('change',updateProgress);});
document.querySelector('#reset-progress').addEventListener('click',()=>{document.querySelectorAll('[data-step]').forEach(el=>el.checked=false);updateProgress();});
document.querySelectorAll('[data-filter]').forEach(btn=>btn.addEventListener('click',()=>{const filter=btn.dataset.filter;document.querySelectorAll('[data-filter]').forEach(el=>el.setAttribute('aria-pressed',String(el===btn)));document.querySelectorAll('[data-category]').forEach(el=>el.hidden=filter!=='all'&&el.dataset.category!==filter);const count=document.querySelectorAll('[data-category]:not([hidden])').length;document.querySelector('#file-count').textContent=`${count} ${count===1?'download group':'download groups'}`;}));
choosePalette(selected);updateProgress();route();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'configure_pongfetch_palette',title:'Choose PongFetch colours',description:'Select one of the three PongFetch colour combinations in the visible local preview. Does not place an order.',inputSchema:{type:'object',properties:{palette:{type:'string',enum:palettes.map(p=>p.id)}},required:['palette'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){const index=palettes.findIndex(p=>p.id===input?.palette);if(index<0||Object.keys(input).some(k=>k!=='palette'))throw new Error('Choose sunshine, tangerine or poolside.');choosePalette(index);return{palette:palettes[index].name,frame:palettes[index].frame,lettering:palettes[index].letter,cap:palettes[index].cap};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}

fetch("downloads/manifest.json").then(response=>{if(!response.ok)throw new Error("Download metadata unavailable");return response.json();}).then(files=>{document.querySelectorAll("[data-file-size]").forEach(el=>{const entry=files[el.dataset.fileSize];if(entry&&Number.isFinite(entry.bytes))el.textContent=" · "+(entry.bytes>=1048576?(entry.bytes/1048576).toFixed(1)+" MB":Math.ceil(entry.bytes/1024)+" KB");});}).catch(()=>{});
